use std::collections::VecDeque;
use std::fs::{File, OpenOptions};
use std::io::Write;
use std::sync::atomic::{AtomicBool, AtomicU64, AtomicUsize, Ordering};
use std::sync::Arc;
use std::thread::{self, JoinHandle};
use std::time::{Duration, Instant};

use anyhow::Result;
use arc_swap::ArcSwap;
use arrayvec::ArrayVec;
use crossbeam_queue::ArrayQueue;
use rtrb::{Consumer, Producer, RingBuffer};
use tracing::{debug, info, warn};

/// Lock-free, bounded MPMC queue used as the candidate sink within a single
/// dirty-event sim sweep. Multiple sim worker threads push concurrently; the
/// `sim_loop` drains the sink into the SPSC `Producer<Candidate>` going to the
/// REVM stage. Sized to absorb the worst case (one candidate per (route × grid
/// bucket) for the cap'd route fanout) without ever blocking a producer.
pub(crate) type CandidateSink = ArrayQueue<Candidate>;

/// Number of sim worker shards (1 inline on the sim thread + `SIM_WORKERS-1`
/// persistent helper threads). The helpers are spawned ONCE at `sim_loop` start
/// and poll a preallocated inbox — never per dirty event, which is the spawn
/// cost the §0.4 ultra-low-latency rule forbids. Set to **2** for the c8g.2xlarge
/// (8 vCPU) core layout: sim thread on core 3 (fast lane) + 1 helper on core 4
/// (full-lane shard). This frees core 5 for the state-writer to own (so it no
/// longer shares core 2 with the parser, which would re-arm the timer tick under
/// `nohz_full`). On a larger instance (c8g.4xlarge, 16 vCPU) raise this and extend
/// the isolated-core set accordingly.
const SIM_WORKERS_DEFAULT: usize = 2;
/// Hard ceiling on sim worker shards. On the 8-vCPU box the sim fan-out can occupy
/// cores 3..=6; beyond 4 it starves revm/shadow/rx (which own cores 5..=7). The route
/// fan-out partitions cleanly by `i % sim_workers`, so 2→4 ~halves the fan-out
/// wall-clock (the code below records SIM_WORKERS=4 measured 135ms→77ms on a broad
/// route universe). 2026-07-05: made runtime-configurable — was pinned at `const 2`.
const SIM_WORKERS_MAX: usize = 4;

/// Pure clamp for the `SIM_WORKERS` env value (unit-tested independent of the env):
/// unset → `SIM_WORKERS_DEFAULT` (capped at `max`); `0` → `1`; above `max` → `max`.
fn clamp_sim_workers(raw: Option<usize>, max: usize) -> usize {
    let max = max.max(1);
    match raw {
        Some(n) => n.clamp(1, max),
        None => SIM_WORKERS_DEFAULT.min(max),
    }
}

/// Runtime sim worker-shard count (read once): `SIM_WORKERS` env, default 2, clamped to
/// `[1, SIM_WORKERS_MAX]`. NOTE (2026-07-10): the effective count is further clamped by
/// `sim_helper_core_plan` — helpers only pin to cores no other hot thread owns, so on the
/// 8-vCPU box the effective maximum is 2 (main on core 3 + one helper on core 4). Raising
/// `SIM_WORKERS` beyond the free-core budget no longer silently stacks helpers onto the
/// state-writer/validator cores; it clamps and warns.
fn sim_workers() -> usize {
    static V: std::sync::OnceLock<usize> = std::sync::OnceLock::new();
    *V.get_or_init(|| {
        let raw = std::env::var("SIM_WORKERS")
            .ok()
            .and_then(|s| s.trim().parse::<usize>().ok());
        clamp_sim_workers(raw, SIM_WORKERS_MAX)
    })
}

/// Cores OWNED by other pinned hot threads on the 8-vCPU §7.3 layout — verified live via the
/// `§7.3 pinned <label> → core N` boot lines: 0 = os/bg (shadow, logsub, resync, pindrift),
/// 1 = engine-rx, 2 = parser, 3 = engine-sim (main), 5 = engine-state-writer, 6 = engine-revm,
/// 7 = engine-submit. Core 4 is the only free helper core on this topology; larger instances
/// (16 vCPU) expose 8+ via `SIM_HELPER_CORES`.
const SIM_HELPER_OWNED_CORES: &[usize] = &[0, 1, 2, 3, 5, 6, 7];

/// §7.3 core-pin layout — the SINGLE SOURCE OF TRUTH for which physical core each pinned hot thread
/// owns. The microsecond FAST LANE (feed → rx → decode → sim/size → express ring → submit) and the
/// REVM validator lane MUST occupy DISJOINT cores: a stall/backlog/lock-hold anywhere in the REVM
/// lane must never migrate onto, or steal a scheduler slice from, a fast-lane core. `pin_to_core`
/// uses these consts so the layout is defined once, and [`core_pins::fast_lane_is_disjoint_from_revm`]
/// (unit-tested) guards the invariant — if anyone later re-pins a fast-lane thread onto core 4/6 the
/// guard fails at test time rather than silently coupling the lanes on the box.
pub(crate) mod core_pins {
    /// Fast-lane: relay RX (feed ingestion).
    pub const RX: usize = 1;
    /// Fast-lane: JSON parser / decode.
    pub const PARSER: usize = 2;
    /// Fast-lane: sim + sizing (sole producer of the express ring).
    pub const SIM: usize = 3;
    /// Fast-lane: state-writer (single writer of the resident pool-state mirror).
    pub const STATE_WRITER: usize = 5;
    /// Fast-lane: submit (sole consumer of the express ring; core 7).
    pub const SUBMIT: usize = 7;
    /// REVM lane: the REVM validator + exotic lane.
    pub const REVM: usize = 6;
    /// REVM lane: the mirror-feed advancer's RECOMMENDED core (env `ADVANCER_CORE`, default 0 = os/bg;
    /// operators set 4 so full-feed re-execution never shares a fast-lane core — GPT-5.6-sol review).
    pub const ADVANCER_RECOMMENDED: usize = 4;

    /// Every core the fast lane pins. Kept next to the pin sites so the guard reads the same truth.
    pub const FAST_LANE: [usize; 5] = [RX, PARSER, SIM, STATE_WRITER, SUBMIT];
    /// The REVM-lane cores the fast lane must never overlap: the validator (6) and the advancer's
    /// hot placement (4). The advancer's DEFAULT is core 0 — the shared os/bg core, which the fast
    /// lane never pins — so both advancer placements stay off every fast-lane core.
    pub const REVM_LANE: [usize; 2] = [REVM, ADVANCER_RECOMMENDED];

    /// The isolation predicate: no fast-lane core coincides with any REVM-lane core.
    pub fn fast_lane_is_disjoint_from_revm() -> bool {
        FAST_LANE.iter().all(|f| !REVM_LANE.contains(f))
    }
}

/// Resolve which physical cores the `sim_workers - 1` helper shards may pin to, and clamp the
/// effective worker count to what actually fits.
///
/// 2026-07-10 box post-mortem (sim_ns needle-flat at 1.01ms): `SIM_WORKERS=4` silently pinned
/// engine-sim-2 onto core 5 (state-writer) and engine-sim-3 onto core 6 (REVM validator) — the
/// old `3 + shard_id` ladder with no ownership check. Every DISPATCHED event's fork-join barrier
/// then waited ≥1 scheduler slice (~1ms) whenever those owned cores were CPU-busy (validator
/// prewarm/backlog on the box run; the same collision is 07-09's sim p90=681µs/p99=1.67ms tail).
/// Helpers now take only provably-free cores; over-asking clamps with a loud WARN instead of
/// silently degrading the fast-lane critical path.
///
/// Pure for testability: `requested` = the clamped `SIM_WORKERS` value; `helper_cores_env` =
/// the raw `SIM_HELPER_CORES` env (comma-separated core list for larger topologies).
fn sim_helper_core_plan(requested: usize, helper_cores_env: Option<&str>) -> (usize, Vec<usize>) {
    let want_helpers = requested.saturating_sub(1);
    if want_helpers == 0 {
        return (1, Vec::new());
    }
    let candidates: Vec<usize> = match helper_cores_env {
        Some(s) => s
            .split(',')
            .filter_map(|t| t.trim().parse::<usize>().ok())
            .collect(),
        // Default ladder starts at the first free core (4) and walks up — same start as the
        // old scheme, but the ownership filter below stops it stacking onto 5/6/7.
        None => (0..want_helpers).map(|h| 4 + h).collect(),
    };
    let mut cores: Vec<usize> = Vec::new();
    for c in candidates {
        if SIM_HELPER_OWNED_CORES.contains(&c) {
            warn!(
                core = c,
                "SIM helper core is OWNED by another pinned hot thread (state-writer@5, revm@6, \
                 submit@7); dropping it — set SIM_HELPER_CORES to genuinely free cores on larger \
                 instances"
            );
            continue;
        }
        if !cores.contains(&c) {
            cores.push(c);
        }
        if cores.len() == want_helpers {
            break;
        }
    }
    let effective = 1 + cores.len();
    if effective < requested {
        warn!(
            requested,
            effective,
            helper_cores = ?cores,
            "SIM_WORKERS clamped: not enough free helper cores on this topology (8-vCPU box \
             supports 2: sim main on core 3 + one helper on core 4)"
        );
    }
    (effective, cores)
}

/// Route-fanout size below which the sim thread evaluates inline (single-threaded)
/// instead of dispatching to the helper pool. Most dirty events produce only a
/// handful of positive-edge routes after the §16 product cull, and for those the
/// cross-thread dispatch + fork-join barrier costs more than the work itself.
const SIM_PARALLEL_THRESHOLD: usize = 24;

/// Lane-1 size: top-K routes evaluated FIRST for minimal time-to-first-candidate.
const LANE1_K: usize = 16;
/// Lane-2 size: broad score-ordered sweep after lane 1.
const SIM_TOPK: usize = 48;

/// [A4] Whether the `sim_workers-1` helper shards can never fire, given the per-event eval
/// fanout cap. `sim_loop`'s parallel-dispatch branch runs only when a lane's route count
/// EXCEEDS `SIM_PARALLEL_THRESHOLD`; a lane holds at most `eval_cap` routes (`split_eval_lanes*`
/// splits the top `eval_cap`), so when `eval_cap <= SIM_PARALLEL_THRESHOLD` the helpers stay
/// parked and their core (4 on the 8-vCPU box) is effectively free — the operator can then set
/// SIM_WORKERS=1 and reclaim it for the fork-warmer/advancer. Pure for testability (mirrors
/// `sim_helper_core_plan`).
fn sim_helpers_inert(sim_workers: usize, eval_cap: usize) -> bool {
    sim_workers > 1 && eval_cap <= SIM_PARALLEL_THRESHOLD
}

/// The sizing-admission seam: take the top `eval_topk` SCORE-ORDERED routes (caller has
/// already run `partial_sort_desc_topk`) and split them lane1-first. `SIM_EVAL_TOPK`
/// bounds SIZING cost only — the scan/score coverage upstream stays wide, and because
/// `scored` is descending, a cap always keeps the highest-spot-edge routes (finite
/// byte-exact edges outrank the exotic 1.0+1e-9 sentinel by construction).
/// Exotic families with no cheap closed-form spot rate fold their score to this
/// neutral-low sentinel (see the score loop): passes the `>1.0` prune (never culled)
/// but ranks below any finite realizable edge. Doubling as an ORIGIN MARKER in the
/// lane split: a score `<= EXOTIC_UNSCORED_RANK` identifies a sentinel-ranked route.
const EXOTIC_UNSCORED_RANK: f64 = 1.0 + 1e-9;

fn split_eval_lanes(
    scored: &[(RouteId, f64)],
    eval_topk: usize,
) -> (ArrayVec<RouteId, LANE1_K>, ArrayVec<RouteId, SIM_TOPK>) {
    split_eval_lanes_budgeted(scored, eval_topk, usize::MAX)
}

/// Lane split with a SENTINEL BUDGET (measured 2026-07-11: at K=16 only ~1.4 of 16 lane
/// routes complete sizing — the rest are sentinel-ranked exotics burning ~20µs each of
/// evaluation overhead, 313µs of the 331µs sim p50). Finite-edge routes fill lanes
/// freely up to `eval_topk`; sentinel-ranked routes are admitted only while the budget
/// lasts. Exotic COVERAGE is retained: budgeted sentinels are still sized every event,
/// the rotating tail re-laps the rest, and the on-chain minNetProfit revert stays the
/// capital guard. `usize::MAX` = legacy (no sentinel limit).
fn split_eval_lanes_budgeted(
    scored: &[(RouteId, f64)],
    eval_topk: usize,
    sentinel_budget: usize,
) -> (ArrayVec<RouteId, LANE1_K>, ArrayVec<RouteId, SIM_TOPK>) {
    let mut lane1: ArrayVec<RouteId, LANE1_K> = ArrayVec::new();
    let mut lane2: ArrayVec<RouteId, SIM_TOPK> = ArrayVec::new();
    let mut admitted = 0usize;
    let mut sentinels = 0usize;
    for (rid, p) in scored.iter() {
        if admitted >= eval_topk {
            break;
        }
        if *p <= EXOTIC_UNSCORED_RANK {
            if sentinels >= sentinel_budget {
                continue; // over budget: skip sizing this lap (tail re-laps it)
            }
            sentinels += 1;
        }
        if admitted < LANE1_K {
            let _ = lane1.try_push(*rid);
        } else {
            let _ = lane2.try_push(*rid);
        }
        admitted += 1;
    }
    (lane1, lane2)
}

/// Head budget of the per-event route collection: the shape-budgeted passes collect exactly
/// this many routes from the score-ordered front of the dirty pools' CSR slices — IDENTICAL
/// to the pre-2026-07-10 behaviour (cap 256), preserved as the always-scanned hot head.
const SIM_HEAD_BUDGET: usize = 256;
/// Hard capacity of the per-event scan set: head + rotating tail. Measured on the real
/// 40k-route cache (hub slice 5,631): head collect 16.3µs, +tail-256 walk ≈ +4µs, scan+score
/// 512 = 4.7µs (+2.5), select 512 = 1.4µs (+0.5) — the full widening costs ≈ +7µs/event on
/// hub events against a permanent-blindness fix (today: 256/5,631 unique routes FOREVER;
/// with the tail: 95% of the hub slice scanned within ~20 events ≈ 3s).
const SIM_SEEN_CAP_MAX: usize = 512;

/// Pure clamp for `SIM_TAIL_SLOTS` (unit-tested): unset → the full tail budget
/// (`SIM_SEEN_CAP_MAX - SIM_HEAD_BUDGET` = 256); `0` disables rotation (exact legacy
/// behaviour); values are clamped to the tail budget.
fn clamp_sim_tail_slots(raw: Option<usize>) -> usize {
    let budget = SIM_SEEN_CAP_MAX - SIM_HEAD_BUDGET;
    raw.unwrap_or(budget).min(budget)
}

/// Runtime rotating-tail slot count (read once): `SIM_TAIL_SLOTS` env.
fn sim_tail_slots() -> usize {
    static V: std::sync::OnceLock<usize> = std::sync::OnceLock::new();
    *V.get_or_init(|| {
        clamp_sim_tail_slots(
            std::env::var("SIM_TAIL_SLOTS")
                .ok()
                .and_then(|s| s.trim().parse::<usize>().ok()),
        )
    })
}

/// One shard of a dirty-event route fanout handed to a persistent sim helper.
/// `routes` is shared immutably for the duration of the fork-join (the sim thread
/// blocks on the completion barrier before the `Arc` is dropped), so helpers read
/// it lock-free; each helper processes the indices `i % SIM_WORKERS == shard_id`.
struct SimJob {
    routes: Arc<[RouteId]>,
    /// Wall clock retained for cross-host/event correlation.
    recv_ns: u64,
    /// Same-host RX stamp used exclusively for duration measurement.
    recv_mono_raw_ns: u64,
    seq: u64,
    gas_snap: engine_gas::GasSnapshot,
}

