                                    let out_of_window = match (
                                        cur.initialised_ticks.first(),
                                        cur.initialised_ticks.last(),
                                    ) {
                                        (Some(f), Some(l)) => *tick < f.tick || *tick > l.tick,
                                        _ => true,
                                    };
                                    let mut ns = cur;
                                    ns.sqrt_price_x96 = *sqrt_price_x96;
                                    ns.tick = *tick;
                                    ns.liquidity = *liquidity;
                                    // 2026-07-10 param-guard review F1: the window refetch MUST use
                                    // the spacing of the state being published, NOT the boot-time
                                    // `plan` tuple — after a live tickSpacing repair (60->10) the
                                    // boot value would re-fetch a stale-grid window and silently
                                    // reintroduce the exact off-grid-ticks-invisible bug the guard
                                    // exists to prevent (and the drift compare can't see it).
