                        let changed = view.kernel.n_coins != cur.kernel.n_coins
                            || (0..view.kernel.n_coins)
                                .any(|k| view.kernel.balances[k] != cur.kernel.balances[k])
                            || view.kernel.a_param != cur.kernel.a_param
                            || view.kernel.fee != cur.kernel.fee;
