    /// 2026-07-09 corpus forensics: `REVM_BLOCK_CTX` is a boot-time `OnceLock`, so all 14,772
    /// records of a 4h soak claimed the BOOT pin (5 unique snapshot_blocks across 715 repins) —
    /// unusable for state-matched replay. The writer must follow the validator's LIVE pin: after
    /// every repin the record's snapshot_block/block_env/block_timestamp reflect the CURRENT fork.
    #[test]
    fn writer_tracks_live_pin_across_repins() {
        let (detection, candidate, snap) = writer_fixture();

        // Simulate the boot pin, then a light repin that advances pin + env, then one that
        // advances the pin but keeps the env (feed timestamp not yet surfaced → ts=0).
        revm_note_pin_advance(482_095_610, Some((482_095_610, 1_783_609_000)));
        revm_note_pin_advance(482_150_001, Some((482_150_001, 1_783_622_500)));
        let row = write_fixture_row(&detection, &candidate, &snap);
        assert_eq!(
            row["snapshot_block"].as_u64(),
            Some(482_150_001),
            "record must carry the CURRENT pin, not the boot pin"
        );
        assert_eq!(row["block_env"].as_u64(), Some(482_150_001));
        assert_eq!(row["block_timestamp"].as_u64(), Some(1_783_622_500));

        // Pin advances without a feed timestamp: snapshot_block moves, env stays.
        revm_note_pin_advance(482_150_777, None);
        let row = write_fixture_row(&detection, &candidate, &snap);
        assert_eq!(row["snapshot_block"].as_u64(), Some(482_150_777));
        assert_eq!(
            row["block_env"].as_u64(),
            Some(482_150_001),
            "block_env must only advance when set_block_env actually ran"
        );
        assert_eq!(row["block_timestamp"].as_u64(), Some(1_783_622_500));
    }

