    /// The record carries the new `verdict` + `reason` Dune keys on top of the legacy columns and
    /// the full Dune-match schema.
    #[test]
    fn candidate_record_value_carries_verdict_and_reason() {
        let (detection, candidate, snap) = writer_fixture();
        let line = candidate_record_line(
            None,
            Some(1),
            &detection,
            &candidate,
            444,
            None,
            [0xAB; 20],
            "not_executed",
            "reject_cooldown_skip",
            &[],
            &snap,
            0,
            0,
            [0u8; 20],
            "0x",
            1_000,
            "rejected",
            "reject_cooldown_skip",
        );
        let v: serde_json::Value =
            serde_json::from_str(line.trim()).expect("record line is valid JSON");
        assert_eq!(v["verdict"], "rejected");
        assert_eq!(v["reason"], "reject_cooldown_skip");
        // Continuity: the legacy columns are still emitted unchanged.
        assert_eq!(v["revm_result"], "not_executed");
        assert_eq!(v["reject_reason"], "reject_cooldown_skip");
        // Dune-match keys are still populated on a thin (no-execution) record.
        assert_eq!(v["route_id"].as_u64(), Some(candidate.route_id.0 as u64));
        assert_eq!(v["trigger_seq"].as_u64(), Some(candidate.seq));
        assert!(v["detect_to_submit_ready_ns"].is_null());
        assert_eq!(v["latency_clock"], "CLOCK_MONOTONIC_RAW");
    }

