    /// The producer API enqueues an allocation-free `Copy` verdict (the only work a hot lane does).
    #[test]
    fn ledger_tx_push_thin_enqueues_copy_verdict() {
        let (_detection, candidate, _snap) = writer_fixture();
        let queue = std::sync::Arc::new(crossbeam_queue::ArrayQueue::<LedgerMsg>::new(4));
        let tx = CandidateLedgerTx {
            queue: queue.clone(),
            balance_slot: None,
            block: None,
        };
        tx.push_thin(
            candidate,
            "rejected",
            "express_fastlane_walk_reject",
            [0xCD; 20],
            false,
        );
        match queue.pop() {
            Some(LedgerMsg::Thin(t)) => {
                assert_eq!(t.verdict, "rejected");
                assert_eq!(t.reason, "express_fastlane_walk_reject");
                assert_eq!(t.mantis, [0xCD; 20]);
                assert_eq!(t.cand.seq, candidate.seq);
                assert!(t.decision_mono_raw_ns >= candidate_detected_mono_raw_ns(&t.cand));
                assert!(t.submit_ready_mono_raw_ns.is_none());
                assert_eq!(t.cand.route_id.0, candidate.route_id.0);
            }
            _ => panic!("expected a Thin ledger message"),
        }
    }

    /// The background writer serialises a thin verdict (with verdict/reason) AND appends a prebuilt
    /// line verbatim — one JSONL row per drained message — then exits on shutdown+empty.
    #[test]
    fn ledger_writer_serialises_thin_and_prebuilt_line() {
        let (detection, candidate, snap) = writer_fixture();
        let gas = std::sync::Arc::new(engine_gas::GasOracle::new(snap, 1_000));
        let queue = crossbeam_queue::ArrayQueue::<LedgerMsg>::new(8);
        queue
            .push(LedgerMsg::Thin(ThinLedgerRecord {
                cand: candidate,
                decision_mono_raw_ns: 444,
                submit_ready_mono_raw_ns: None,
                verdict: "rejected",
                reason: "notional_cap_drop",
                mantis: [0u8; 20],
            }))
            .ok()
            .expect("push thin");
        queue
            .push(LedgerMsg::Line("{\"prebuilt\":true}".to_string()))
            .ok()
            .expect("push line");
        let path = std::env::temp_dir().join(format!(
            "mantis_ledger_{}_{:?}.jsonl",
            std::process::id(),
            std::thread::current().id()
        ));
        let file = std::fs::File::create(&path).expect("temp ledger file");
        // shutdown pre-set ⇒ drain everything, then exit (no background thread needed for the test).
        let shutdown = std::sync::atomic::AtomicBool::new(true);
        candidate_ledger_writer(
            &shutdown,
            &queue,
            file,
            None,
            Some(465_686_729),
            &detection,
            &gas,
            1_000,
        );
        let body = std::fs::read_to_string(&path).expect("read ledger");
        let _ = std::fs::remove_file(&path);
        let lines: Vec<&str> = body.lines().collect();
        assert_eq!(lines.len(), 2, "one JSONL row per drained message");
        let thin: serde_json::Value =
            serde_json::from_str(lines[0]).expect("thin row is valid JSON");
        assert_eq!(thin["verdict"], "rejected");
        assert_eq!(thin["reason"], "notional_cap_drop");
        assert_eq!(thin["revm_result"], "not_executed");
        // The prebuilt (core-6 REVM) line is appended verbatim.
        assert_eq!(lines[1], "{\"prebuilt\":true}");
    }

