    #[derive(Clone, Copy)]
    enum F07RxForm {
        OwnedStream,
        SlabStream,
        OwnedSeqpacket,
        SlabSeqpacket,
    }

    impl F07RxForm {
        fn label(self) -> &'static str {
            match self {
                Self::OwnedStream => "owned-stream",
                Self::SlabStream => "slab-stream",
                Self::OwnedSeqpacket => "owned-seqpacket",
                Self::SlabSeqpacket => "slab-seqpacket",
            }
        }

        fn assertion(self) -> &'static str {
            match self {
                Self::OwnedStream => "[C10-F07-OWNED-STREAM-CONFLICT]",
                Self::SlabStream => "[C10-F07-SLAB-STREAM-CONFLICT]",
                Self::OwnedSeqpacket => "[C10-F07-OWNED-SEQPACKET-CONFLICT]",
                Self::SlabSeqpacket => "[C10-F07-SLAB-SEQPACKET-CONFLICT]",
            }
        }
    }

    fn real_validator_vc(
        detection: &Arc<DetectionContext>,
        candidate: Candidate,
        snap: engine_gas::GasSnapshot,
        generation: u64,
    ) -> ValidatedCandidate {
        let prepared = prepare_submission(
            detection,
            &snap,
            candidate.route_id,
            candidate.amount_in,
            candidate.gross_profit,
            50,
        )
        .expect("T6 real validator accept must prepare a submittable candidate");
        let (mut producer, mut consumer) = RingBuffer::<ValidatedCandidate>::new(2);
        assert!(
            !push_validated_candidate(
                &mut producer,
                candidate,
                prepared,
                None,
                generation,
            ),
            "T6 real validator accept must push through the production VC constructor"
        );
        consumer
            .pop()
            .ok()
            .expect("T6 real validator accept must emit a ValidatedCandidate")
    }

    fn real_express_vc(
        detection: &Arc<DetectionContext>,
        candidate: Candidate,
        snap: engine_gas::GasSnapshot,
        generation: u64,
        integrity: &engine_state::publication::ReplayIntegrityShared,
    ) -> ValidatedCandidate {
        let gas = Arc::new(engine_gas::GasOracle::new(snap, 10_000));
        let (mut producer, mut consumer) = RingBuffer::<ExpressCandidate>::new(2);
        producer
            .push(ExpressCandidate::plain(candidate, generation))
            .ok()
            .expect("T6 real express admission must push its stamped ring item");
        let mut cooldown = RejectCooldown::new(std::time::Duration::ZERO);
        express_pop_prepare(
            &mut consumer,
            &mut cooldown,
            detection,
            &gas,
            1_000,
            [0u8; 20],
            integrity,
        )
        .expect("T6 real express accept must emit a ValidatedCandidate")
    }

    fn case12_real_vc_terminal() {
        let _guard = FEED_FAIL_TEST_LOCK
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        reset_feed_authority_for_test();
        let (detection, candidates, snap) =
            super::candidate_record_writer_tests::known_good_u3_pancake_express_fixture();

        // Positive control: the actual validator accept-site constructor emits a VC which reaches
        // the same HotSpare terminal and makes exactly one clean physical-post observation.
        let clean_integrity = Arc::new(engine_state::publication::ReplayIntegrityShared::new());
        let clean_generation = clean_integrity
            .capture_clean_pin_generation()
            .expect("clean control generation");
        let clean_vc = real_validator_vc(
            &detection,
            candidates[0],
            snap,
            clean_generation,
        );
        assert_eq!(
            clean_vc.integrity_pin_generation, clean_generation,
            "[C12-VALIDATOR-REAL-ACCEPT-STAMP] clean validator VC retains its accept generation"
        );
        let clean_kill = KillSwitches::new();
        let clean_permit = capture_feed_authority(&clean_kill).expect("clean control permit");
        let clean_posts = Arc::new(AtomicU64::new(0));
        let mut clean_submit = counting_hot_spare(&clean_posts, true, true);
        clean_submit
            .submit_authorized(&clean_vc.prepared.calldata, &mut || {
                wire_authorization_current(
                    clean_permit,
                    &clean_integrity,
                    clean_vc.integrity_pin_generation,
                )
            })
            .expect("[C12-CLEAN-CONTROL-ONE-RAW] clean real VC must reach the clean terminal");
        assert_eq!(
            clean_posts.load(Ordering::Relaxed),
            1,
            "[C12-CLEAN-CONTROL-ONE-RAW] clean real VC performs exactly one raw post"
        );

        for (lane, observed) in [("validator", false), ("validator", true), ("express", false),
            ("express", true)] {
            for (primary_warm, spare_warm, topology) in [
                (true, true, "WARM-PRIMARY"),
                (false, true, "WARM-SPARE"),
                (false, false, "RECONNECT"),
            ] {
                let integrity = Arc::new(engine_state::publication::ReplayIntegrityShared::new());
                let generation = integrity
                    .capture_clean_pin_generation()
                    .expect("real terminal clean generation");
                let vc = if lane == "validator" {
                    let vc = real_validator_vc(&detection, candidates[1], snap, generation);
                    assert_eq!(
                        vc.integrity_pin_generation, generation,
                        "[C12-VALIDATOR-REAL-ACCEPT-STAMP] validator VC carries the clean accept stamp"
                    );
                    vc
                } else {
                    let vc = real_express_vc(
                        &detection,
                        candidates[2],
                        snap,
                        generation,
                        &integrity,
                    );
                    assert_eq!(
                        vc.integrity_pin_generation, generation,
                        "[C12-EXPRESS-REAL-ACCEPT-STAMP] express VC carries the stored admission stamp"
                    );
                    vc
                };
                let kill = KillSwitches::new();
                let permit = capture_feed_authority(&kill).expect("real terminal permit");
                assert!(
                    wire_authorization_current(permit, &integrity, vc.integrity_pin_generation),
                    "[C12-FAULT-AFTER-ACCEPT] real VC is authorized before the injected interleaving"
                );
                let posts = Arc::new(AtomicU64::new(0));
                let mut submit = counting_hot_spare_fault_after_authorize(
                    &posts,
                    primary_warm,
                    spare_warm,
                    &integrity,
                );
                let failure = if observed {
                    submit
                        .submit_observed_authorized(
                            &vc.prepared.calldata,
                            &mut |_| {},
                            &mut || {
                                wire_authorization_current(
                                    permit,
                                    &integrity,
                                    vc.integrity_pin_generation,
                                )
                            },
                        )
                        .expect_err("[C12-OBSERVED-ZERO-RAW] faulted observed VC must refuse")
                } else {
                    submit
                        .submit_authorized(&vc.prepared.calldata, &mut || {
                            wire_authorization_current(
                                permit,
                                &integrity,
                                vc.integrity_pin_generation,
                            )
                        })
                        .expect_err("[C12-WARM-PRIMARY-ZERO-RAW] faulted VC must refuse")
                };
                assert!(
                    matches!(failure.err, engine_submit::SubmitError::AuthorityRevoked),
                    "[C12-AUTHORITY-REVOKED] {lane} {topology} terminal must report AuthorityRevoked"
                );
                assert_eq!(
                    failure.delivery,
                    engine_submit::DeliveryState::DefinitelyNotWritten,
                    "[C12-DEFINITELY-NOT-WRITTEN] {lane} {topology} terminal is safe to reclaim"
                );
                assert_eq!(
                    posts.load(Ordering::Relaxed),
                    0,
                    "[C12-WARM-PRIMARY-ZERO-RAW] [C12-WARM-SPARE-ZERO-RAW] \
                     [C12-RECONNECT-ZERO-RAW] [C12-OBSERVED-ZERO-RAW] {lane} {topology} \
                     fault-after-accept emits no raw post"
                );
                assert!(
                    integrity.faulted(),
                    "[C12-FAULT-AFTER-ACCEPT] transport interleaving must leave the shared pin faulted"
                );
                reset_feed_authority_for_test();
            }
        }
        reset_feed_authority_for_test();
    }

    fn case13_real_vc_generation_terminal() {
        let _guard = FEED_FAIL_TEST_LOCK
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        reset_feed_authority_for_test();
        let (detection, candidates, snap) =
            super::candidate_record_writer_tests::known_good_u3_pancake_express_fixture();
        let integrity = Arc::new(engine_state::publication::ReplayIntegrityShared::new());
        let old_generation = integrity
            .capture_clean_pin_generation()
            .expect("[C13-VALIDATOR-REAL-STAMP-N] clean old generation");
        let validator_vc = real_validator_vc(&detection, candidates[0], snap, old_generation);
        assert_eq!(
            validator_vc.integrity_pin_generation, old_generation,
            "[C13-VALIDATOR-REAL-STAMP-N] validator VC is stamped at N"
        );
        let express_generation = express_admission_pin_generation(&integrity)
            .expect("[C13-EXPRESS-ADMISSION-STAMP-N] clean express admission at N");
        assert_eq!(
            express_generation, old_generation,
            "[C13-EXPRESS-ADMISSION-STAMP-N] express admission captures the same N"
        );
        let express_vc = real_express_vc(
            &detection,
            candidates[1],
            snap,
            express_generation,
            &integrity,
        );
        assert_eq!(
            express_vc.integrity_pin_generation, old_generation,
            "[C13-EXPRESS-ACCEPT-STAMP-N] express VC carries N unchanged"
        );

        // Keep an independently retained old-N express item for the pop race position.
        let (mut retained_producer, mut retained_consumer) =
            RingBuffer::<ExpressCandidate>::new(2);
        retained_producer
            .push(ExpressCandidate::plain(candidates[2], old_generation))
            .ok()
            .expect("[C13-EXPRESS-ADMISSION-STAMP-N] retain old-N express candidate");

        let kill = KillSwitches::new();
        let old_permit = capture_feed_authority(&kill).expect("old-N validator permit");
        integrity.publish_fault(engine_state::publication::REPLAY_FLAG_POISONED);
        let new_generation = integrity.repin_clear();
        assert_eq!(
            new_generation,
            old_generation + 1,
            "[C13-TEST-ONLY-ATOMIC-N-PLUS-ONE] test-only packed repin advances N to N+1"
        );
        assert!(
            integrity.replay_integrity_current(new_generation),
            "[C13-TEST-ONLY-ATOMIC-N-PLUS-ONE] N+1 flags are clear only for the new generation"
        );

        let validator_posts = Arc::new(AtomicU64::new(0));
        let mut validator_submit = counting_hot_spare(&validator_posts, true, true);
        let validator_failure = validator_submit
            .submit_authorized(&validator_vc.prepared.calldata, &mut || {
                wire_authorization_current(
                    old_permit,
                    &integrity,
                    validator_vc.integrity_pin_generation,
                )
            })
            .expect_err("[C13-OLD-VALIDATOR-AUTHORITY-REVOKED] old-N validator must refuse");
        assert!(
            matches!(
                validator_failure.err,
                engine_submit::SubmitError::AuthorityRevoked
            ),
            "[C13-OLD-VALIDATOR-AUTHORITY-REVOKED] old-N validator reports AuthorityRevoked"
        );
        assert_eq!(
            validator_failure.delivery,
            engine_submit::DeliveryState::DefinitelyNotWritten,
            "[C13-DEFINITELY-NOT-WRITTEN] old-N validator is definitely not written"
        );
        assert_eq!(
            validator_posts.load(Ordering::Relaxed),
            0,
            "[C13-OLD-N-ZERO-RAW] old-N validator emits no raw post"
        );

        let express_posts = Arc::new(AtomicU64::new(0));
        let mut express_submit = counting_hot_spare(&express_posts, false, true);
        let express_failure = express_submit
            .submit_authorized(&express_vc.prepared.calldata, &mut || {
                wire_authorization_current(
                    old_permit,
                    &integrity,
                    express_vc.integrity_pin_generation,
                )
            })
            .expect_err("[C13-OLD-EXPRESS-AUTHORITY-REVOKED] old-N express VC must refuse");
        assert!(
            matches!(express_failure.err, engine_submit::SubmitError::AuthorityRevoked),
            "[C13-OLD-EXPRESS-AUTHORITY-REVOKED] old-N express reports AuthorityRevoked"
        );
        assert_eq!(
            express_posts.load(Ordering::Relaxed),
            0,
            "[C13-OLD-N-ZERO-RAW] old-N express VC emits no raw post"
        );

        let mut cooldown = RejectCooldown::new(std::time::Duration::ZERO);
        assert!(
            express_pop_prepare(
                &mut retained_consumer,
                &mut cooldown,
                &detection,
                &Arc::new(engine_gas::GasOracle::new(snap, 10_000)),
                1_000,
                [0u8; 20],
                &integrity,
            )
            .is_none(),
            "[C13-OLD-EXPRESS-POP-DECLINE] retained old-N express item must fail at pop"
        );

        let fresh_generation = express_admission_pin_generation(&integrity)
            .expect("[C13-FRESH-N-PLUS-ONE-ONE-RAW] fresh N+1 admission control");
        assert_eq!(fresh_generation, new_generation);
        let fresh_vc = real_express_vc(
            &detection,
            candidates[0],
            snap,
            fresh_generation,
            &integrity,
        );
        let fresh_permit = capture_feed_authority(&kill).expect("fresh N+1 permit");
        let fresh_posts = Arc::new(AtomicU64::new(0));
        let mut fresh_submit = counting_hot_spare(&fresh_posts, true, true);
        fresh_submit
            .submit_authorized(&fresh_vc.prepared.calldata, &mut || {
                wire_authorization_current(
                    fresh_permit,
                    &integrity,
                    fresh_vc.integrity_pin_generation,
                )
            })
            .expect("[C13-FRESH-N-PLUS-ONE-ONE-RAW] fresh N+1 VC must write");
        assert_eq!(
            fresh_posts.load(Ordering::Relaxed),
            1,
            "[C13-FRESH-N-PLUS-ONE-ONE-RAW] fresh N+1 performs exactly one raw post"
        );
        reset_feed_authority_for_test();
    }

    /// Build the common real-accept fixture used by the D2 fault rows: the validator VC is
    /// emitted by the production constructor and the express item is admitted/stamped before the
    /// row's real replay/feed seam is exercised.
    fn real_fault_fixture() -> (
        Arc<DetectionContext>,
        Candidate,
        engine_gas::GasSnapshot,
        ValidatedCandidate,
        rtrb::Consumer<ExpressCandidate>,
        Arc<engine_state::publication::ReplayIntegrityShared>,
    ) {
        reset_feed_authority_for_test();
        let (detection, candidates, snap) =
            super::candidate_record_writer_tests::known_good_u3_pancake_express_fixture();
        let integrity = Arc::new(engine_state::publication::ReplayIntegrityShared::new());
        let generation = integrity
            .capture_clean_pin_generation()
            .expect("real fault fixture starts on a clean pin");
        let candidate = candidates[0];
        let validator_vc = real_validator_vc(&detection, candidate, snap, generation);
        let (mut express_producer, express_consumer) =
            RingBuffer::<ExpressCandidate>::new(2);
        express_producer
            .push(ExpressCandidate::plain(candidates[1], generation))
            .ok()
            .expect("real fault fixture retains an admitted express item");
        (
            detection,
            candidate,
            snap,
            validator_vc,
            express_consumer,
            integrity,
        )
    }

    fn assert_real_vc_zero_raw(
        label: &str,
        integrity: &Arc<engine_state::publication::ReplayIntegrityShared>,
        vc: &ValidatedCandidate,
    ) {
        // Some real feed seams (ordinal loss and the F07 payload sentinel) also trip the
        // process-global legacy feed latch.  Clear only that test attribution latch here; the
        // shared packed replay authority and the VC's captured generation remain untouched.
        reset_feed_authority_for_test();
        let terminal_kill = KillSwitches::new();
        terminal_kill.feed.close(now_ns());
        let permit = capture_feed_authority(&terminal_kill)
            .expect("fault terminal keeps feed permit healthy");
        let posts = Arc::new(AtomicU64::new(0));
        let mut submit = counting_hot_spare(&posts, true, true);
        let failure = submit
            .submit_authorized(&vc.prepared.calldata, &mut || {
                wire_authorization_current(permit, integrity, vc.integrity_pin_generation)
            })
            .expect_err("faulted real VC must be refused before raw write");
        assert!(
            matches!(failure.err, engine_submit::SubmitError::AuthorityRevoked),
            "{label} [C2-AUTHORITY-REVOKED] faulted real VC reports AuthorityRevoked"
        );
        assert_eq!(
            failure.delivery,
            engine_submit::DeliveryState::DefinitelyNotWritten,
            "{label} [C2-DEFINITELY-NOT-WRITTEN] faulted real VC is definitely not written"
        );
        assert_eq!(
            posts.load(Ordering::Relaxed),
            0,
            "{label} [C2-ZERO-RAW-POST] [C3-BELOW-ZERO-RAW] [C3-BETWEEN-ZERO-RAW] [C3-ABOVE-ZERO-RAW] real VC emits zero raw posts"
        );
    }

    fn assert_real_express_pop_declines(
        label: &str,
        detection: &Arc<DetectionContext>,
        snap: engine_gas::GasSnapshot,
        integrity: &Arc<engine_state::publication::ReplayIntegrityShared>,
        express_consumer: &mut rtrb::Consumer<ExpressCandidate>,
    ) {
        let mut cooldown = RejectCooldown::new(std::time::Duration::ZERO);
        assert!(
            express_pop_prepare(
                express_consumer,
                &mut cooldown,
                detection,
                &Arc::new(engine_gas::GasOracle::new(snap, 10_000)),
                1_000,
                [0u8; 20],
                integrity,
            )
            .is_none(),
            "{label} [C10-F01-POP-DECLINE] retained real express item must fail at pop"
        );
    }

    fn assert_real_fault_terminal(
        label: &str,
        detection: &Arc<DetectionContext>,
        snap: engine_gas::GasSnapshot,
        integrity: &Arc<engine_state::publication::ReplayIntegrityShared>,
        vc: &ValidatedCandidate,
        mut express_consumer: rtrb::Consumer<ExpressCandidate>,
    ) {
        assert!(
            integrity.faulted(),
            "{label} [C2-FIRST-EVICTION-RISK-POISONS] [C3-POISONED-AT-REAL-ENQUEUE-SEAM] [C4-WHOLE-PIN-POISONED] [C5-RECOVERY-FAILURE-POISONS] fault seam poisons the shared pin"
        );
        assert!(
            express_admission_pin_generation(integrity).is_none(),
            "{label} [C10-F01-SIM-DECLINE] post-fault sim admission emits no express entry"
        );
        assert_real_vc_zero_raw(label, integrity, vc);
        assert_real_express_pop_declines(
            label,
            detection,
            snap,
            integrity,
            &mut express_consumer,
        );
    }

    fn case2_real_vc_terminal() {
        let _guard = FEED_FAIL_TEST_LOCK
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let (detection, _candidate, snap, vc, express_consumer, integrity) = real_fault_fixture();
        let target = [0xD2; 20];
        let mut exec = engine_revm::ForkExecutor::new(
            super::drain_replay_tests::ReplayCodeFetcher {
                target,
                code: vec![0x00],
            },
        );
        let mut pending = VecDeque::new();
        let mut dedup = crate::revm_replay::BoundedTxDedup::new(1);
        let mut fail_tracker = crate::revm_replay::ReplayFailTracker::new(2);
        let first_q = Arc::new(ArrayQueue::new(1));
        first_q
            .push(super::drain_replay_tests::signed_event(1, 0x11, target))
            .unwrap();
        let first = drain_revm_state_replay_queue(
            &first_q,
            &mut pending,
            Some(&mut exec),
            &mut dedup,
            &mut fail_tracker,
            &integrity,
            Some(ResolvedFeedCutoff::Through(FeedReplayCursor::new(1, 0))),
            None,
            None,
            None,
        );
        assert_eq!(first.committed, 1, "[C2-REAL-VC-STAMP] first replay applies before eviction risk");
        let second_q = Arc::new(ArrayQueue::new(1));
        second_q
            .push(super::drain_replay_tests::signed_event(2, 0x22, target))
            .unwrap();
        let second = drain_revm_state_replay_queue(
            &second_q,
            &mut pending,
            Some(&mut exec),
            &mut dedup,
            &mut fail_tracker,
            &integrity,
            Some(ResolvedFeedCutoff::Through(FeedReplayCursor::new(2, 0))),
            None,
            None,
            None,
        );
        assert_eq!(
            second.committed,
            1,
            "[C2-FIRST-EVICTION-RISK-POISONS] the first distinct full-window insert reaches the real drain seam"
        );
        assert_real_fault_terminal(
            "[C2-FIRST-EVICTION-RISK-POISONS] [C2-REAL-VC-STAMP] [C2-AUTHORITY-REVOKED] [C2-DEFINITELY-NOT-WRITTEN] [C2-ZERO-RAW-POST]",
            &detection,
            snap,
            &integrity,
            &vc,
            express_consumer,
        );
        reset_feed_authority_for_test();
    }

    fn case3_real_vc_terminals() {
        let _guard = FEED_FAIL_TEST_LOCK
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let (detection, base, snap, _fixture_vc, mut express_consumer, integrity) =
            real_fault_fixture();
        let generation = integrity.current_pin_generation();
        let below = real_validator_vc(
            &detection,
            Candidate {
                seq: 90,
                inner_ordinal: 0,
                ..base
            },
            snap,
            generation,
        );
        let between = real_validator_vc(
            &detection,
            Candidate {
                seq: 90,
                inner_ordinal: 2,
                ..base
            },
            snap,
            generation,
        );
        let above = real_validator_vc(
            &detection,
            Candidate {
                seq: 90,
                inner_ordinal: 4,
                ..base
            },
            snap,
            generation,
        );
        let queue = Arc::new(ArrayQueue::new(1));
        queue
            .push(RevmReplayEvent {
                recv_ns: 0,
                seq: 1,
                inner_ordinal: 0,
                tx_hash: [0; 32],
                envelope: Arc::<[u8]>::from(&[0x02, 0xc0][..]),
            })
            .unwrap();
        let mut earliest = None;
        assert!(!enqueue_revm_state_replay(
            &queue,
            &super::parsed_ring_fail_closed_tests::replay_parsed(90, 1),
            &integrity,
            &mut earliest,
        ));
        assert!(!enqueue_revm_state_replay(
            &queue,
            &super::parsed_ring_fail_closed_tests::replay_parsed(90, 3),
            &integrity,
            &mut earliest,
        ));
        assert_eq!(
            earliest,
            Some(FeedReplayCursor::new(90, 1)),
            "[C3-EARLIEST-HOLE-MIN] real enqueue losses retain the earliest diagnostic hole"
        );
        assert!(
            !integrity.replay_integrity_current(generation),
            "[C3-PIN-NONCURRENT] [C3-WHOLE-PIN-NOT-SUFFIX] poisoned pin is not current for any VC cursor"
        );
        assert_real_vc_zero_raw("[C3-BELOW-ZERO-RAW] [C3-REAL-VC-STAMP]", &integrity, &below);
        assert_real_vc_zero_raw(
            "[C3-BETWEEN-ZERO-RAW] [C3-REAL-VC-STAMP]",
            &integrity,
            &between,
        );
        assert_real_vc_zero_raw("[C3-ABOVE-ZERO-RAW] [C3-REAL-VC-STAMP]", &integrity, &above);
        assert_real_express_pop_declines(
            "[C3-WHOLE-PIN-NOT-SUFFIX]",
            &detection,
            snap,
            &integrity,
            &mut express_consumer,
        );
        reset_feed_authority_for_test();
    }

