    #[test]
    fn state_checkpoint_json_records_fork_mismatch_verdict() {
        let line = state_checkpoint_json_for_hashes(
            7,
            &meta(PoolKind::UniswapV3),
            PoolId(3),
            [0x11u8; 32],
            Some([0x22u8; 32]),
            "fork_compare",
        );

        assert!(line.contains(r#""fork_state_hash":"0x2222222222222222222222222222222222222222222222222222222222222222""#));
        assert!(line.contains(r#""equal":false"#));
        assert!(line.contains(r#""differences":["local_state_hash_mismatch"]"#));
        assert!(line.contains(r#""source":"fork_compare""#));
    }

