    /// F6 (codex item 11) RED→GREEN: the receipt path GUARANTEES a Fluid pool's wake. `fluid_receipt_
    /// wake` writes the fresh snapshot AND bumps the generation (the signal detection re-reads on) AND
    /// returns the pool so `apply_receipt_logs_value` adds it to `updated` and the boundary
    /// `push_dirty_event` re-prices it. Before the fix the receipt replayer wrote the snapshot but
    /// neither bumped the generation nor added the pool to `updated`, so — with bounded file replay
    /// SKIPPING the live poller — the fresh Fluid state was PERMANENTLY unwoken (detection never
    /// re-priced the pool).
    #[test]
    fn fluid_receipt_write_bumps_generation_and_returns_the_pool_for_wake() {
        let mut builder = UniverseBuilder::new();
        let token0 = builder.add_token([0xA0u8; 20], 6, RiskClass::CentralisedStable);
        let token1 = builder.add_token([0xB0u8; 20], 6, RiskClass::CentralisedStable);
        let pool = builder
            .add_fluid_pool(
                [0x3Cu8; 20],
                token0,
                token1,
                VenueId(0),
                1_000,
                FluidPoolSnapshot::default(),
            )
            .expect("fluid pool");
        let universe = builder.build();
        let n_pools = universe.pools.len();
        let detection = Arc::new(DetectionContext {
            universe: std::sync::Arc::new(universe),
            route_table: RouteTable::new(),
            pool_to_hot_routes: CsrBuilder::new(n_pools as u32).build(),
            selectors: SelectorRegistry::canonical(),
            telemetry: Arc::new(engine_discovery::PoolTelemetry::new(vec![1u64 << 32; n_pools])),
            family_quote_active: crate::runtime_policy::default_active_families().dense(),
        });
        let slot = detection.universe.pools.meta(pool).state_slot;
        let mut permit = engine_state::publication::StateWriterPermit::test_mint();
        let txn = permit.begin_txn();

        let gen0 = detection.universe.pools.generation(pool);
        let woken = fluid_receipt_wake(&detection, &txn, pool, slot, FluidPoolSnapshot::default());

        assert_eq!(
            woken, pool,
            "returns the pool so apply_receipt_logs_value adds it to `updated` (boundary wake)"
        );
        assert_eq!(
            detection.universe.pools.generation(pool),
            gen0 + 1,
            "the generation bump IS the wake signal — detection re-reads on it (never silently unwoken)"
        );
    }

