    /// WI-06 F7 (codex item 9-secondary) RED→GREEN: the Balancer resync writes a kernel-only
    /// `FamilyWrite`, so the publisher PRESERVES the resident tokens + poolId. That is byte-identical
    /// to the parent's full refresh IFF the live identity matches — which this runtime check PROVES
    /// (immutable pool ⇒ always matches). A reorder / poolId drift / count change would misalign the
    /// freshly-built balances against the resident token map, so it returns false and the caller fails
    /// closed (poison + skip) instead of silently corrupting quotes.
    #[test]
    fn balancer_resync_identity_proves_preserve_and_fails_closed_on_drift() {
        let t = |a: u8| {
            let mut x = [0u8; 20];
            x[0] = a;
            x
        };
        let pid = [0x07u8; 32];
        let cur = [t(1), t(2), t(3)];
        // Immutable pool: live identity matches resident ⇒ preserve-resident is byte-identical.
        assert!(balancer_identity_matches_resident(
            &[t(1), t(2), t(3)],
            None,
            &pid,
            &cur,
            &pid,
            3
        ));
        // Live BPT at index 1 (not a tradable coin) is skipped — the tradable coins still match.
        assert!(balancer_identity_matches_resident(
            &[t(1), t(9), t(2), t(3)],
            Some(1),
            &pid,
            &cur,
            &pid,
            3
        ));
        // Reordered live tokens ⇒ balances would misalign ⇒ fail closed.
        assert!(!balancer_identity_matches_resident(
            &[t(2), t(1), t(3)],
            None,
            &pid,
            &cur,
            &pid,
            3
        ));
        // Different poolId ⇒ wrong pool ⇒ fail closed.
        assert!(!balancer_identity_matches_resident(
            &[t(1), t(2), t(3)],
            None,
            &[0x08u8; 32],
            &cur,
            &pid,
            3
        ));
        // Token-count drift ⇒ fail closed.
        assert!(!balancer_identity_matches_resident(&[t(1), t(2)], None, &pid, &cur, &pid, 3));
    }

    /// WI-06 F7 (codex item 9-secondary): the Curve resync preserves resident coins (kernel-only
    /// write); this runtime check proves the immutable-coin invariant and fails closed on any drift.
    #[test]
    fn curve_resync_identity_proves_preserve_and_fails_closed_on_drift() {
        let t = |a: u8| {
            let mut x = [0u8; 20];
            x[0] = a;
            x
        };
        let cur = [t(1), t(2), t(3)];
        assert!(curve_tokens_match_resident(&[t(1), t(2), t(3)], 3, &cur, 3));
        // Reordered ⇒ misalign ⇒ fail closed.
        assert!(!curve_tokens_match_resident(&[t(2), t(1), t(3)], 3, &cur, 3));
        // Coin-count drift ⇒ fail closed.
        assert!(!curve_tokens_match_resident(&[t(1), t(2), t(3)], 2, &cur, 3));
        assert!(!curve_tokens_match_resident(&[t(1), t(2)], 2, &cur, 3));
    }

