    /// WI-06 F2 (codex item 9-primary): a V3 tick-crossing resync must NOT roll canonical state
    /// backward. The former path submitted TWO batches — a full price/tick/liquidity batch, then a
    /// window batch that RE-SNAPSHOTTED resident state; if the first was still queued, the second
    /// read the OLD price/tick/liquidity and committed it AFTER the first (rollback) with a second
    /// bump. The fix composes both payloads from the SAME snapshot into ONE batch. This test drives
    /// the fixed `v3_resync_combined_write` path and asserts the newest values survive with exactly
    /// one bump — and (as a RED-documenting sub-assertion) that the old two-batch/stale-resnapshot
    /// sequence WOULD have rolled backward.
    #[test]
    fn queued_first_batch_cannot_be_overwritten_by_stale_second() {
        use engine_state::publication::{BarrierOriginClass, FamilyWrite};
        let start = V3State {
            sqrt_price_x96: U256::from(1_000u64),
            tick: 60,
            liquidity: 1_000,
            fee_pips: 500,
            tick_spacing: 60,
            initialised_ticks: vec![TickInfo {
                tick: -60,
                liquidity_net: -10,
            }],
        };
        let new_price = U256::from(5_000u64);
        let new_tick = 180;
        let new_liq = 2_000u128;
        let fresh_window = vec![
            engine_rpc::V3TickSnapshot {
                tick: 120,
                liquidity_gross: 200,
                liquidity_net: 20,
            },
            engine_rpc::V3TickSnapshot {
                tick: 240,
                liquidity_gross: 200,
                liquidity_net: -20,
            },
        ];
        let expected_ticks: Vec<TickInfo> = fresh_window
            .iter()
            .map(|t| TickInfo {
                tick: t.tick,
                liquidity_net: t.liquidity_net,
            })
            .collect();

        // --- The OLD two-batch / stale-resnapshot pattern DEMONSTRABLY rolls state backward. ---
        // (These two batches are submitted with UNVALIDATED_PRIOR_GENERATION so this block isolates
        // F2's rollback — the *composition* defect — from F3's generation check, which is a separate
        // backstop that would otherwise POISON the stale second batch. F2 fixes the root cause by
        // never producing the second batch at all.)
        {
            let (detection, slot, pool, mut publisher) = v3_resync_fixture(start.clone());
            let sender = publisher.command_sender();
            let mut permit = engine_state::publication::StateWriterPermit::test_mint();
            let mut txn = permit.begin_txn();
            let submit_unvalidated = |ns: V3State| {
                sender
                    .submit_batch(engine_state::publication::StateMutationBatch::single(
                        BarrierOriginClass::Resync,
                        engine_state::publication::PoolStateMutation {
                            pool,
                            point: transitional_placeholder_point(),
                            expected_prior_generation:
                                engine_state::publication::UNVALIDATED_PRIOR_GENERATION,
                            pre_replay_seq:
                                engine_state::publication::UNVALIDATED_PRE_REPLAY_SEQ,
                            shadow_pre_image: None,
                            write: FamilyWrite::V3(ns),
                        },
                    ))
                    .unwrap();
            };
            let gen0 = detection.universe.pools.generation(pool);
            // Batch 1: new price/tick/liquidity (old window), from the current snapshot.
            let cur = detection.universe.v3_state.snapshot(slot);
            let mut ns1 = cur.clone();
            ns1.sqrt_price_x96 = new_price;
            ns1.tick = new_tick;
            ns1.liquidity = new_liq;
            submit_unvalidated(ns1);
            // Batch 1 is STILL QUEUED (no drain). The window path re-snapshots RESIDENT state —
            // which is still the OLD price because batch 1 has not committed.
            let stale = detection.universe.v3_state.snapshot(slot);
            let mut ns2 = stale.clone();
            ns2.initialised_ticks = expected_ticks.clone();
            submit_unvalidated(ns2);
            publisher.drain_commands_each(&mut txn, |_| {});
            let final_state = detection.universe.v3_state.snapshot(slot);
            let bumps = detection.universe.pools.generation(pool) - gen0;
            // This is the defect: the newest price was overwritten by the stale second batch, and
            // the pool double-bumped. (If this ever STOPS holding, the two-batch anti-pattern was
            // removed some other way — fine, but the combined path below is the sanctioned fix.)
            assert_eq!(
                final_state.sqrt_price_x96,
                start.sqrt_price_x96,
                "two-batch reproduction: price should have rolled BACKWARD to the stale value"
            );
            assert_eq!(bumps, 2, "two-batch reproduction: pool double-bumps");
        }

        // --- The FIX: ONE combined batch composed from ONE snapshot. Newest values, ONE bump. ---
        {
            let (detection, slot, pool, mut publisher) = v3_resync_fixture(start.clone());
            let sender = publisher.command_sender();
            let mut permit = engine_state::publication::StateWriterPermit::test_mint();
            let mut txn = permit.begin_txn();
            let gen0 = detection.universe.pools.generation(pool);
            let cur = detection.universe.v3_state.snapshot(slot);
            let mut base = cur.clone();
            base.sqrt_price_x96 = new_price;
            base.tick = new_tick;
            base.liquidity = new_liq;
            let combined = v3_resync_combined_write(base, &fresh_window);
            submit_offthread_family_write(
                &sender,
                BarrierOriginClass::Resync,
                pool,
                gen0,
                engine_state::publication::UNVALIDATED_PRE_REPLAY_SEQ,
                None,
                transitional_placeholder_point(),
                FamilyWrite::V3(combined),
            )
            .unwrap();
            publisher.drain_commands_each(&mut txn, |_| {});
            let final_state = detection.universe.v3_state.snapshot(slot);
            let bumps = detection.universe.pools.generation(pool) - gen0;
            assert_eq!(
                final_state.sqrt_price_x96, new_price,
                "combined write: the newest price must survive (no rollback)"
            );
            assert_eq!(final_state.tick, new_tick);
            assert_eq!(final_state.liquidity, new_liq);
            assert_eq!(
                final_state.initialised_ticks, expected_ticks,
                "combined write: the fresh window must be applied in the SAME batch"
            );
            assert_eq!(bumps, 1, "a tick-crossing resync must bump exactly once");
        }
    }

    /// WI-06 F2 fix-round-2 (codex items 5 + 9-residual): the resync `expected_prior_generation`
    /// must be captured WITH the source snapshot, not sampled at submit. If a publisher commit
    /// lands on the pool BETWEEN the snapshot and the submit, the stale snapshot-derived write must
    /// be REFUSED (its captured generation no longer matches current), never relabelled with the
    /// newer generation and applied over the fresh state. RED reproduces the submit-time sample:
    /// the stale write is accepted and rolls the fresh interleaved commit backward.
    #[test]
    fn interleaved_commit_between_snapshot_and_submit_is_refused() {
        use engine_state::publication::{BarrierOriginClass, FamilyWrite};
        let start = V3State {
            sqrt_price_x96: U256::from(1_000u64),
            tick: 60,
            liquidity: 1_000,
            fee_pips: 500,
            tick_spacing: 60,
            initialised_ticks: vec![],
        };
        let (detection, slot, pool, mut publisher) = v3_resync_fixture(start);
        let sender = publisher.command_sender();
        let mut permit = engine_state::publication::StateWriterPermit::test_mint();
        let mut txn = permit.begin_txn();

        // SNAPSHOT TIME: capture the pool generation together with the base state the resync write
        // is computed from.
        let snapshot_generation = detection.universe.pools.generation(pool);
        let cur = detection.universe.v3_state.snapshot(slot);
        let mut stale = cur.clone();
        stale.sqrt_price_x96 = U256::from(1_111u64); // resync's view, derived from `cur`

        // INTERLEAVE: a fresh feed/publisher commit lands on THIS pool before the resync write is
        // submitted — advancing the generation past `snapshot_generation`.
        let mut fresh = cur.clone();
        fresh.sqrt_price_x96 = U256::from(9_999u64);
        submit_offthread_family_write(
            &sender,
            BarrierOriginClass::Resync,
            pool,
            detection.universe.pools.generation(pool), // captured NOW, before the interleave commit
            engine_state::publication::UNVALIDATED_PRE_REPLAY_SEQ,
            None,
            transitional_placeholder_point(),
            FamilyWrite::V3(fresh),
        )
        .unwrap();
        publisher.drain_commands_each(&mut txn, |_| {});
        assert_eq!(
            detection.universe.v3_state.snapshot(slot).sqrt_price_x96,
            U256::from(9_999u64),
            "the interleaved fresh commit must apply"
        );
        assert!(
            detection.universe.pools.generation(pool) > snapshot_generation,
            "the interleave must advance the generation past the snapshot"
        );

        // SUBMIT the STALE resync write (computed from the OLD snapshot). Carrying the snapshot-time
        // generation, the publisher must REFUSE it (stale-over-new), never roll `9_999` back.
        submit_offthread_family_write(
            &sender,
            BarrierOriginClass::Resync,
            pool,
            snapshot_generation,
            engine_state::publication::UNVALIDATED_PRE_REPLAY_SEQ,
            None,
            transitional_placeholder_point(),
            FamilyWrite::V3(stale),
        )
        .unwrap();
        publisher.drain_commands_each(&mut txn, |_| {});

        assert_eq!(
            detection.universe.v3_state.snapshot(slot).sqrt_price_x96,
            U256::from(9_999u64),
            "stale-over-new must be REFUSED — the fresh interleaved commit must NOT be rolled back"
        );
    }

    /// WI-06 F2 (codex item 3): a V3 tick crossing publishes as ONE batch → ONE generation bump,
    /// carrying BOTH the new price/tick/liquidity AND the fresh tick window composed from a single
    /// snapshot. Guards against re-introducing a second independent window batch (double bump).
    #[test]
    fn v3_tick_crossing_is_single_batch_single_bump() {
        use engine_state::publication::{BarrierOriginClass, FamilyWrite};
        let start = V3State {
            sqrt_price_x96: U256::from(1_000u64),
            tick: 60,
            liquidity: 1_000,
            fee_pips: 500,
            tick_spacing: 60,
            initialised_ticks: vec![TickInfo {
                tick: -60,
                liquidity_net: -10,
            }],
        };
        let (detection, slot, pool, mut publisher) = v3_resync_fixture(start);
        let sender = publisher.command_sender();
        let mut permit = engine_state::publication::StateWriterPermit::test_mint();
        let mut txn = permit.begin_txn();

        let fresh_window = vec![engine_rpc::V3TickSnapshot {
            tick: 120,
            liquidity_gross: 200,
            liquidity_net: 20,
        }];
        let mut base = detection.universe.v3_state.snapshot(slot);
        base.sqrt_price_x96 = U256::from(9_999u64);
        base.tick = 300;
        base.liquidity = 3_333;
        let combined = v3_resync_combined_write(base, &fresh_window);

        let gen0 = detection.universe.pools.generation(pool);
        let mut committed_batches = 0usize;
        submit_offthread_family_write(
            &sender,
            BarrierOriginClass::Resync,
            pool,
            gen0,
            engine_state::publication::UNVALIDATED_PRE_REPLAY_SEQ,
            None,
            transitional_placeholder_point(),
            FamilyWrite::V3(combined),
        )
        .unwrap();
        publisher.drain_commands_each(&mut txn, |_| committed_batches += 1);

        assert_eq!(committed_batches, 1, "exactly one batch committed for the crossing pool");
        assert_eq!(
            detection.universe.pools.generation(pool) - gen0,
            1,
            "exactly one generation bump"
        );
        let s = detection.universe.v3_state.snapshot(slot);
        assert_eq!(s.sqrt_price_x96, U256::from(9_999u64));
        assert_eq!(s.tick, 300);
        assert_eq!(s.liquidity, 3_333);
        assert_eq!(
            s.initialised_ticks,
            vec![TickInfo {
                tick: 120,
                liquidity_net: 20
            }]
        );
    }

