    fn assert_gate4_final_v3_receipt_log_applies(
        pool_addr: &str,
        initial_sqrt: &str,
        initial_tick: i32,
        initial_liquidity: u128,
        final_sqrt: &str,
        final_tick: i32,
        final_liquidity: u128,
        tx_hash: &str,
    ) {
        let mut builder = UniverseBuilder::new();
        let token0 = builder.add_token([0xA0u8; 20], 18, RiskClass::Permissionless);
        let token1 = builder.add_token([0xB0u8; 20], 18, RiskClass::Permissionless);
        let pool_addr = parse_address(pool_addr).expect("pool addr");
        let final_sqrt = U256::from_str_radix(final_sqrt, 10).expect("sqrt");
        let pool = builder
            .add_v3_pool(
                pool_addr,
                PoolKind::UniswapV3,
                token0,
                token1,
                VenueId(0),
                500,
                10,
                V3State {
                    sqrt_price_x96: U256::from_str_radix(initial_sqrt, 10).expect("initial sqrt"),
                    tick: initial_tick,
                    liquidity: initial_liquidity,
                    fee_pips: 500,
                    tick_spacing: 10,
                    initialised_ticks: vec![TickInfo {
                        tick: initial_tick,
                        liquidity_net: 0,
                    }],
                },
            )
            .expect("v3 pool");
        let universe = builder.build();
        let n_pools = universe.pools.len();
        let detection = Arc::new(DetectionContext {
            universe: std::sync::Arc::new(universe),
            route_table: RouteTable::new(),
            pool_to_hot_routes: CsrBuilder::new(n_pools as u32).build(),
            selectors: SelectorRegistry::canonical(),
            telemetry: Arc::new(engine_discovery::PoolTelemetry::new(vec![
                1u64 << 32;
                n_pools
            ])),
            family_quote_active: crate::runtime_policy::default_active_families().dense(),
        });
        let topics = log_apply_topics();
        let addr_map = build_log_addr_map(&detection);
        let receipt = json!({
            "logs": [{
                "address": hex_prefixed(&pool_addr),
                "topics": [topic_hex(&topics.v3swap)],
                "data": v3_swap_data(final_sqrt, final_liquidity, final_tick),
                "transactionHash": tx_hash,
                "blockNumber": "0x1bc1d0c9",
            }]
        });
        let dirty_queue = Arc::new(ArrayQueue::new(4));
        let targeted_q = Arc::new(ArrayQueue::new(4));
        let log_updates = Arc::new(AtomicU64::new(0));
        let mut seq = 99;

        let updated = apply_receipt_logs_value(
            &receipt,
            &addr_map,
            &topics,
            &detection,
            &dirty_queue,
            &targeted_q,
            &log_updates,
            &mut seq,
        );

        assert_eq!(updated.as_slice(), &[pool]);
        let state = detection
            .universe
            .v3_state
            .snapshot(detection.universe.pools.meta(pool).state_slot);
        assert_eq!(state.sqrt_price_x96, final_sqrt);
        assert_eq!(state.tick, final_tick);
        assert_eq!(state.liquidity, final_liquidity);
        assert_eq!(log_updates.load(Ordering::Relaxed), 1);
    }

